1	package com.loja.servico;
2	
3	import com.loja.dto.CheckoutRequest;
4	import com.loja.dto.CheckoutResponse;
5	import com.loja.dto.ItemRequest;
6	import com.loja.enums.Cupom;
7	import com.loja.enums.FormaPagamento;
8	import com.loja.enums.NivelClube;
9	import com.loja.enums.Regiao;
10	import com.loja.enums.TipoEntrega;
11	import com.loja.estrategia.AjustePagamentoResult;
12	import com.loja.estrategia.CupomFactory;
13	import com.loja.estrategia.EstrategiaAjustePagamento;
14	import com.loja.estrategia.EstrategiaCupom;
15	import com.loja.estrategia.EstrategiaFrete;
16	import com.loja.estrategia.FreteFactory;
17	import com.loja.estrategia.PagamentoFactory;
18	import com.loja.util.ArredondadorMoeda;
19	import com.loja.validacao.ValidadorCheckout;
20	import java.math.BigDecimal;
21	import org.springframework.stereotype.Service;
22	
23	@Service
24	public class ServicoCheckout {
25	    private final ValidadorCheckout validador = new ValidadorCheckout();
26	
27	    public CheckoutResponse calcularResumo(CheckoutRequest request) {
28	        String erro = validador.validar(request);
29	        if (erro != null) {
30	            throw new ErroCheckout(erro);
31	        }
32	
33	        BigDecimal subtotalProdutos = calcularSubtotal(request.getItens());
34	        subtotalProdutos = ArredondadorMoeda.arredondar(subtotalProdutos);
35	
36	        TipoEntrega tipoEntrega = TipoEntrega.fromString(request.getModalidadeEntrega());
37	        Cupom cupom = Cupom.fromString(request.getCupom());
38	        NivelClube nivelClube = NivelClube.fromString(request.getNivelClube());
39	        Regiao regiao = Regiao.fromString(request.getRegiao());
40	        FormaPagamento formaPagamento = FormaPagamento.fromString(request.getFormaPagamento());
41	        int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
42	
43	        BigDecimal descontoCupom = calcularDescontoCupom(cupom, subtotalProdutos, request.getItens(), tipoEntrega);
44	        descontoCupom = ArredondadorMoeda.arredondar(descontoCupom);
45	
46	        BigDecimal pesoTotal = calcularPesoTotal(request.getItens());
47	        BigDecimal frete = calcularFrete(tipoEntrega, pesoTotal, nivelClube);
48	        frete = ArredondadorMoeda.arredondar(frete);
49	        int prazoEntrega = obterPrazoEntrega(tipoEntrega);
50	
51	        BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
52	        seguro = ArredondadorMoeda.arredondar(seguro);
53	
54	        BigDecimal totalAntesAjuste = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
55	
56	        AjustePagamentoResult ajuste = calcularAjustePagamento(formaPagamento, totalAntesAjuste, parcelas);
57	        BigDecimal ajustePagamento = ArredondadorMoeda.arredondar(ajuste.ajuste);
58	
59	        BigDecimal totalFinal = totalAntesAjuste.add(ajuste.ajuste);
60	        totalFinal = ArredondadorMoeda.arredondar(totalFinal);
61	
62	        BigDecimal valorParcela = ArredondadorMoeda.arredondar(ajuste.valorParcela);
63	
64	        BigDecimal creditoProximaCompra = calcularCredito(nivelClube, subtotalProdutos);
65	        creditoProximaCompra = ArredondadorMoeda.arredondar(creditoProximaCompra);
66	
67	        boolean brinde = verificarBrinde(nivelClube, subtotalProdutos);
68	
69	        return new CheckoutResponse(
70	                subtotalProdutos,
71	                descontoCupom,
72	                frete,
73	                prazoEntrega,
74	                seguro,
75	                ajustePagamento,
76	                totalFinal,
77	                ajuste.parcelas,
78	                valorParcela,
79	                creditoProximaCompra,
80	                brinde
81	        );
82	    }
83	
84	    private BigDecimal calcularSubtotal(java.util.List<ItemRequest> itens) {
85	        BigDecimal subtotal = BigDecimal.ZERO;
86	        for (ItemRequest item : itens) {
87	            subtotal = subtotal.add(item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())));
88	        }
89	        return subtotal;
90	    }
91	
92	    private BigDecimal calcularDescontoCupom(Cupom cupom, BigDecimal subtotal, java.util.List<ItemRequest> itens, TipoEntrega tipoEntrega) {
93	        if (cupom == null) {
94	            return BigDecimal.ZERO;
95	        }
96	
97	        EstrategiaCupom estrategia = CupomFactory.criar(cupom, itens);
98	
99	        BigDecimal frete = BigDecimal.ZERO;
100	        if (cupom == Cupom.FRETEGRATIS) {
101	            EstrategiaFrete estrategiaFrete = FreteFactory.criar(tipoEntrega);
102	            BigDecimal pesoTotal = calcularPesoTotal(itens);
103	            frete = estrategiaFrete.calcularCusto(pesoTotal);
104	        }
105	
106	        return estrategia.aplicar(subtotal, frete);
107	    }
108	
109	    private BigDecimal calcularPesoTotal(java.util.List<ItemRequest> itens) {
110	        BigDecimal peso = BigDecimal.ZERO;
111	        for (ItemRequest item : itens) {
112	            peso = peso.add(item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())));
113	        }
114	        return peso;
115	    }
116	
117	    private BigDecimal calcularFrete(TipoEntrega tipoEntrega, BigDecimal pesoTotal, NivelClube nivelClube) {
118	        if (nivelClube == NivelClube.OURO) {
119	            return BigDecimal.ZERO;
120	        }
121	
122	        EstrategiaFrete estrategia = FreteFactory.criar(tipoEntrega);
123	        return estrategia.calcularCusto(pesoTotal);
124	    }
125	
126	    private int obterPrazoEntrega(TipoEntrega tipoEntrega) {
127	        EstrategiaFrete estrategia = FreteFactory.criar(tipoEntrega);
128	        return estrategia.prazo();
129	    }
130	
131	    private BigDecimal calcularSeguro(BigDecimal subtotal, Regiao regiao) {
132	        BigDecimal percentual = obterPercentualSeguro(regiao);
133	        return subtotal.multiply(percentual);
134	    }
135	
136	    private BigDecimal obterPercentualSeguro(Regiao regiao) {
137	        return switch (regiao) {
138	            case SUDESTE, SUL -> new BigDecimal("0.01");
139	            case CENTRO_OESTE -> new BigDecimal("0.015");
140	            case NORTE -> new BigDecimal("0.025");
141	            case NORDESTE -> new BigDecimal("0.02");
142	        };
143	    }
144	
145	    private AjustePagamentoResult calcularAjustePagamento(FormaPagamento formaPagamento, BigDecimal total, int parcelas) {
146	        EstrategiaAjustePagamento estrategia = PagamentoFactory.criar(formaPagamento);
147	        return estrategia.calcular(total, parcelas);
148	    }
149	
150	    private BigDecimal calcularCredito(NivelClube nivelClube, BigDecimal subtotal) {
151	        if (nivelClube == NivelClube.BRONZE) {
152	            return BigDecimal.ZERO;
153	        } else if (nivelClube == NivelClube.PRATA) {
154	            return subtotal.multiply(new BigDecimal("0.02"));
155	        } else if (nivelClube == NivelClube.OURO) {
156	            return subtotal.multiply(new BigDecimal("0.05"));
157	        }
158	        return BigDecimal.ZERO;
159	    }
160	
161	    private boolean verificarBrinde(NivelClube nivelClube, BigDecimal subtotal) {
162	        return nivelClube == NivelClube.OURO && subtotal.compareTo(new BigDecimal("500.00")) > 0;
163	    }
164	}
