1	package com.loja.validacao;
2	
3	import com.loja.dto.CheckoutRequest;
4	import com.loja.dto.ItemRequest;
5	import com.loja.enums.Cupom;
6	import com.loja.enums.FormaPagamento;
7	import com.loja.enums.NivelClube;
8	import com.loja.enums.Regiao;
9	import com.loja.enums.TipoEntrega;
10	import java.math.BigDecimal;
11	
12	public class ValidadorCheckout {
13	
14	    public String validar(CheckoutRequest request) {
15	        // Ordem 1: Carrinho inválido
16	        String erroCarrinho = validarCarrinho(request.getItens());
17	        if (erroCarrinho != null) return erroCarrinho;
18	
19	        // Ordem 2: Nível do clube
20	        if (NivelClube.fromString(request.getNivelClube()) == null) {
21	            return "NIVEL_CLUBE_INVALIDO";
22	        }
23	
24	        // Ordem 3: Região
25	        if (Regiao.fromString(request.getRegiao()) == null) {
26	            return "REGIAO_INVALIDA";
27	        }
28	
29	        // Ordem 4: Modalidade de entrega
30	        TipoEntrega tipo = TipoEntrega.fromString(request.getModalidadeEntrega());
31	        if (tipo == null) {
32	            return "MODALIDADE_INVALIDA";
33	        }
34	
35	        // Ordem 5: Modalidade indisponível
36	        String erroModalidade = validarModalidadeDisponivel(tipo, request.getItens());
37	        if (erroModalidade != null) return erroModalidade;
38	
39	        // Ordem 6: Cupom inválido
40	        Cupom cupom = Cupom.fromString(request.getCupom());
41	        if (request.getCupom() != null && cupom == null) {
42	            return "CUPOM_INVALIDO";
43	        }
44	
45	        // Ordem 7: Cupom não aplicável
46	        if (cupom != null) {
47	            BigDecimal subtotal = calcularSubtotal(request.getItens());
48	            String erroCupom = validarCupomAplicavel(cupom, subtotal);
49	            if (erroCupom != null) return erroCupom;
50	        }
51	
52	        // Ordem 8: Forma de pagamento
53	        FormaPagamento forma = FormaPagamento.fromString(request.getFormaPagamento());
54	        if (forma == null) {
55	            return "FORMA_PAGAMENTO_INVALIDA";
56	        }
57	
58	        // Ordem 9: Parcelamento inválido
59	        int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
60	        String erroParcelamento = validarParcelamento(forma, parcelas);
61	        if (erroParcelamento != null) return erroParcelamento;
62	
63	        // Ordem 10: Forma de pagamento indisponível
64	        String erroFormaPagamento = validarFormaPagamentoDisponivel(forma, request.getItens(), request.getNivelClube());
65	        if (erroFormaPagamento != null) return erroFormaPagamento;
66	
67	        return null;
68	    }
69	
70	    private String validarCarrinho(java.util.List<ItemRequest> itens) {
71	        if (itens == null || itens.isEmpty()) {
72	            return "PEDIDO_INVALIDO";
73	        }
74	        for (ItemRequest item : itens) {
75	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario().signum() <= 0) {
76	                return "PEDIDO_INVALIDO";
77	            }
78	            if (item.getQuantidade() <= 0) {
79	                return "PEDIDO_INVALIDO";
80	            }
81	            if (item.getPesoKg() == null || item.getPesoKg().signum() < 0) {
82	                return "PEDIDO_INVALIDO";
83	            }
84	        }
85	        return null;
86	    }
87	
88	    private String validarModalidadeDisponivel(TipoEntrega tipo, java.util.List<ItemRequest> itens) {
89	        if (tipo == TipoEntrega.MOTOBOY) {
90	            BigDecimal pesoTotal = BigDecimal.ZERO;
91	            for (ItemRequest item : itens) {
92	                pesoTotal = pesoTotal.add(item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())));
93	            }
94	            if (pesoTotal.compareTo(new BigDecimal("5")) > 0) {
95	                return "MODALIDADE_INDISPONIVEL";
96	            }
97	        }
98	        return null;
99	    }
100	
101	    private String validarCupomAplicavel(Cupom cupom, BigDecimal subtotal) {
102	        if (cupom == Cupom.MENOS50) {
103	            if (subtotal.compareTo(new BigDecimal("300.00")) < 0) {
104	                return "CUPOM_NAO_APLICAVEL";
105	            }
106	        }
107	        return null;
108	    }
109	
110	    private String validarParcelamento(FormaPagamento forma, int parcelas) {
111	        if (forma == FormaPagamento.PIX || forma == FormaPagamento.BOLETO) {
112	            if (parcelas != 1) {
113	                return "PARCELAMENTO_INVALIDO";
114	            }
115	        } else if (forma == FormaPagamento.CARTAO) {
116	            if (parcelas < 1 || parcelas > 12) {
117	                return "PARCELAMENTO_INVALIDO";
118	            }
119	        }
120	        return null;
121	    }
122	
123	    private String validarFormaPagamentoDisponivel(FormaPagamento forma, java.util.List<ItemRequest> itens, String nivelClube) {
124	        if (forma == FormaPagamento.BOLETO) {
125	            BigDecimal subtotal = calcularSubtotal(itens);
126	            // Calcula valor aproximado do total para validação
127	            NivelClube nivel = NivelClube.fromString(nivelClube);
128	            if (subtotal.compareTo(new BigDecimal("1000.00")) > 0) {
129	                return "FORMA_PAGAMENTO_INDISPONIVEL";
130	            }
131	        }
132	        return null;
133	    }
134	
135	    private BigDecimal calcularSubtotal(java.util.List<ItemRequest> itens) {
136	        BigDecimal subtotal = BigDecimal.ZERO;
137	        for (ItemRequest item : itens) {
138	            subtotal = subtotal.add(item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())));
139	        }
140	        return subtotal;
141	    }
142	}
