5	
6	public class PagamentoCartao implements EstrategiaAjustePagamento {
7	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
8	
9	    @Override
10	    public AjustePagamentoResult calcular(BigDecimal total, int parcelas) {
11	        if (parcelas <= 3) {
12	            BigDecimal valorParcela = total.divide(
13	                    new BigDecimal(parcelas),
14	                    2,
15	                    RoundingMode.HALF_EVEN
16	            );
17	            BigDecimal totalCalculado = valorParcela.multiply(new BigDecimal(parcelas));
18	            BigDecimal ajuste = totalCalculado.subtract(total);
19	            return new AjustePagamentoResult(ajuste, parcelas, valorParcela);
20	        } else {
21	            BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
22	            BigDecimal potencia = umMaisTaxa.pow(parcelas);
23	            BigDecimal expoente = BigDecimal.ONE.divide(potencia, 15, RoundingMode.HALF_EVEN);
24	            BigDecimal denominador = BigDecimal.ONE.subtract(expoente);
25	            BigDecimal valorParcela = total.multiply(TAXA_JUROS).divide(
26	                    denominador,
27	                    2,
28	                    RoundingMode.HALF_EVEN
29	            );
30	            BigDecimal totalCalculado = valorParcela.multiply(new BigDecimal(parcelas));
31	            BigDecimal ajuste = totalCalculado.subtract(total);
32	            return new AjustePagamentoResult(ajuste, parcelas, valorParcela);
33	        }
34	    }
35	
36	    @Override
37	    public boolean validarParcelas(int parcelas) {
